      "name": "Powder Blue",
      "level": 2,
      "purpose": "Info-state surface — tinted background for status badges and highlight wash."
    },
    {
      "hex": "#7451f2",
      "name": "Iris Violet",
      "level": 3,
      "purpose": "Brand surface — filled CTA, the highest-attention UI layer."
    }
  ],
  "elevation": [
    {
      "style": "rgba(0, 0, 0, 0.2) 0px 2px 4px 0px",
      "element": "Primary CTA button"
    }
